import CoreText
import Foundation
import Metal

// Golden + metric test for the glyph atlas. The committed golden
// (tests/snapshots/atlas/atlas_dump.png) is the deviceGray export of the fixed
// ReferenceAtlas texture, generated by `zig build bench -- --write-reference`.
// The golden compare runs on single-channel R8 bytes through
// SnapshotComparator.compareGray with the same AA tolerance as the BGRA suite.
//
// Because a snapshot golden cannot vouch for itself, the golden compare is paired
// with golden-INDEPENDENT metric asserts derived from the atlas's structure: a
// pinned entry count, pairwise non-overlap, in-bounds placement, and
// internally-consistent occupancy/fill/shelf metrics. These fail if the packer
// double-books a cell or the dump miscounts, independent of the image bytes.
@main
struct AtlasSnapshotTests {
    // The fixed ReferenceAtlas string has this many distinct scalars; a glyph is
    // inserted once per distinct (font, size, glyph), so the atlas holds exactly
    // this many entries. Pins the test to the reference content, not the image.
    private static let expectedEntryCount = 32

    static func main() {
        let device = makeDevice()
        let atlas = ReferenceAtlas.build(device: device)
        let snapshot = atlas.snapshot()

        runGoldenCompare(atlas: atlas)
        runEntryCountMetric(snapshot)
        runNonOverlapMetric(snapshot)
        runInBoundsMetric(snapshot)
        runOccupancyConsistencyMetric(snapshot)
        print("atlas-snapshot-test: all cases passed")
    }

    private static func runGoldenCompare(atlas: Atlas) {
        let grayPixels = AtlasInspector.readTextureBytes(atlas.texture)
        SnapshotComparator.compareGray(
            grayPixels: grayPixels,
            width: atlas.texture.width,
            height: atlas.texture.height,
            goldenName: ReferenceAtlas.goldenName
        )
    }

    private static func runEntryCountMetric(_ snapshot: AtlasSnapshot) {
        precondition(
            snapshot.entries.count == expectedEntryCount,
            "expected \(expectedEntryCount) atlas entries, got \(snapshot.entries.count)"
        )
        print("entries: \(snapshot.entries.count)")
    }

    private static func runNonOverlapMetric(_ snapshot: AtlasSnapshot) {
        let rectangles = snapshot.entries.map(\.placement.pixelRect)
        for first in 0..<rectangles.count {
            for second in (first + 1)..<rectangles.count {
                precondition(
                    !overlaps(rectangles[first], rectangles[second]),
                    "rectangles \(rectangles[first]) and \(rectangles[second]) overlap"
                )
            }
        }
        print("non-overlap: \(rectangles.count) rectangles disjoint")
    }

    private static func runInBoundsMetric(_ snapshot: AtlasSnapshot) {
        for entry in snapshot.entries {
            let rect = entry.placement.pixelRect
            precondition(rect.x >= 0 && rect.y >= 0, "rect origin negative \(rect)")
            precondition(
                rect.x + rect.width <= snapshot.size && rect.y + rect.height <= snapshot.size,
                "rect \(rect) overruns atlas \(snapshot.size)"
            )
            precondition(rect.width > 0 && rect.height > 0, "rect empty \(rect)")
        }
        print("in-bounds: all \(snapshot.entries.count) rectangles within \(snapshot.size)")
    }

    // occupiedPixels must equal the summed rectangle areas, fillRatio must equal
    // occupied / size^2, and shelfCount must be positive — internal consistency
    // that holds regardless of the golden image bytes.
    private static func runOccupancyConsistencyMetric(_ snapshot: AtlasSnapshot) {
        let summedArea = snapshot.entries.reduce(0) { total, entry in
            total + entry.placement.pixelRect.width * entry.placement.pixelRect.height
        }
        precondition(
            snapshot.occupiedPixels == summedArea,
            "occupiedPixels \(snapshot.occupiedPixels) != summed area \(summedArea)"
        )
        let expectedFill = Double(summedArea) / Double(snapshot.size * snapshot.size)
        precondition(
            abs(snapshot.fillRatio - expectedFill) < 1e-9,
            "fillRatio \(snapshot.fillRatio) != \(expectedFill)"
        )
        precondition(snapshot.shelfCount > 0, "shelfCount must be positive, got \(snapshot.shelfCount)")
        precondition(
            snapshot.occupiedPixels > 0 && snapshot.occupiedPixels < snapshot.size * snapshot.size,
            "occupancy out of range: \(snapshot.occupiedPixels) of \(snapshot.size * snapshot.size)"
        )
        print("occupancy: occupied=\(snapshot.occupiedPixels) shelves=\(snapshot.shelfCount) fill=\(snapshot.fillRatio)")
    }

    private static func overlaps(_ first: PackedRectangle, _ second: PackedRectangle) -> Bool {
        let separatedX = first.x + first.width <= second.x || second.x + second.width <= first.x
        let separatedY = first.y + first.height <= second.y || second.y + second.height <= first.y
        return !(separatedX || separatedY)
    }

    private static func makeDevice() -> MTLDevice {
        guard let device = MTLCreateSystemDefaultDevice() else {
            fatalError("Metal is unavailable: MTLCreateSystemDefaultDevice returned nil")
        }
        return device
    }
}
